import{_ as r,l as i,o as e,c as l,v as o,p as s,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"Eaton–Gersovitz 主权违约","description":"","frontmatter":{"title":"Eaton–Gersovitz 主权违约","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/eaton-gersovitz.md","filePath":"econ/eaton-gersovitz.md","lastUpdated":1789023840000}'),c={name:"econ/eaton-gersovitz.md"};function h(A,a,_,m,u,f){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="eaton–gersovitz-主权违约" tabindex="-1">Eaton–Gersovitz 主权违约 <a class="header-anchor" href="#eaton–gersovitz-主权违约" aria-label="Permalink to &quot;Eaton–Gersovitz 主权违约&quot;">​</a></h1><div class="epigraph"><p>主权不能被抵押法庭强制执行，还款靠未来市场准入与产出惩罚；债务是声誉合约，不是 KM 的土地。</p><footer>—— Eaton and Gersovitz, Debt with Potential Repudiation, ReStud 1981</footer></div><p><a href="/econ/global-financial-cycle">上一课</a>的借款人仍是可抵押的私人。主权经常不能被扣押资本。本课缺口是 <strong>Eaton–Gersovitz</strong>：违约的期权与内生利率。不重写全球因子，不把 Arellano 的定量校准提前做完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>私人 KM：不还则失去抵押品。主权：抵押品有限，惩罚是排除在市场之外、贸易或产出损失。Eaton–Gersovitz：政府每期选借新债或违约，债权人要价使期望回报相等，利率含违约溢价。缺口是给「新兴市场利差」一条合约装置，而不是把利差当外生 GK 冲击。</p><p><span class="marginnote">Eaton and Gersovitz, <em>Review of Economic Studies</em> 48(2), 1981, 289–309。Bulow and Rogoff 对声誉能否支持债务的批评（1989）：若能储蓄，惩罚可能不够。后续文献用排除、谈判、政治。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>政府贝尔曼：状态是债与产出。违约：进入惩罚区（一段时间不能借、产出损失），债归零或进谈判。履约：付息、发新债。债价 \\(q(b&#39;,z)= \\mathbb{E}[(1-\\delta&#39;) (1+coupon)/R]\\)。长期债、自我履行的滚动，后课 Arellano 定量化。与财政：一次总付税可还债，但政治上限使有效上像约束。</p>',8)),(e(),s(E,null,{default:t(()=>[p(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%80%BA%E5%8A%A1%E7%8A%B6%E6%80%81%22%5D%20--%3E%20CH%5B%22%E5%B1%A5%E7%BA%A6%E6%88%96%E8%BF%9D%E7%BA%A6%22%5D%0A%20%20CH%20--%3E%20EX%5B%22%E6%8E%92%E9%99%A4%20%2F%20%E4%BA%A7%E5%87%BA%E6%83%A9%E7%BD%9A%22%5D%0A%20%20CH%20--%3E%20SPR%5B%22%E5%86%85%E7%94%9F%E5%88%A9%E5%B7%AE%22%5D%0A%20%20Z%5B%22%E4%BA%A7%E5%87%BA%E5%86%B2%E5%87%BB%22%5D%20--%3E%20CH%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与家庭 Aiyagari：都是不完全执行的债务，惩罚技术不同。主权没有外生的 \\(a\\ge\\underline a\\) 那么干净，排除是均衡对象。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是未来剩余损失对今天诱惑。高债、坏 \\(z\\) 时违约期权价内，利差跳升，滚动危机：即使愿意还，市场不给 \\(q\\) 也会逼违约。这与银行挤兑同构，对象是批发债权人。全球金融周期：中心收紧使 \\(q\\) 下降，把原本可滚动的债推入价内——两课相接。</p><p>Bulow–Rogoff：若违约后仍能在市场上买资产，惩罚弱。现实排除不完美，故有谈判与发市（Arellano 后的 Chatterjee–Eyigungor、Hatchondo–Martinez）。</p><p><span class="marginnote">本课不把评级公司当理论。也不交易 CDS。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定某个国家会不会违约。定量的违约频率与利差匹配是下一课 Arellano。债务可持续的 \\(r-g\\) 会计再下一课，EG 是微观基础。货币主导稀释本币债，与违约是替代，后课。</p><p>后课默认：主权债价含内生违约溢价；执行靠惩罚而非土地抵押。下一课：Arellano 的定量递归。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Eaton–Gersovitz：违约期权 + 排除惩罚 ⇒ 内生利差。</li><li>与 KM 抵押执行不同。</li><li>滚动危机：利差跳升可自我实现式地逼近违约。</li><li>出处：Eaton and Gersovitz, <em>ReStud</em> 1981。</li></ul>',10))])}const g=r(c,[["render",h]]);export{v as __pageData,g as default};
